// OnConflict allows configuring the `ON CONFLICT` / `ON DUPLICATE KEY` clause
// of the `INSERT` statement. For example:
//
//	client.ManagedPackage.Create().
//		SetName(v).
//		OnConflict(
//			// Update the row with the new values
//			// the was proposed for insertion.
//			sql.ResolveWithNewValues(),
//		).
//		// Override some of the fields with custom
//		// update values.
//		Update(func(u *ent.ManagedPackageUpsert) {
//			SetName(v+v).
//		}).
//		Exec(ctx)
func (mpc *ManagedPackageCreate) OnConflict(opts ...sql.ConflictOption) *ManagedPackageUpsertOne {
	mpc.conflict = opts
	return &ManagedPackageUpsertOne{
		create: mpc,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
// as conflict target. Using this option is equivalent to using:
//
//	client.ManagedPackage.Create().
//		OnConflict(sql.ConflictColumns(columns...)).
//		Exec(ctx)
func (mpc *ManagedPackageCreate) OnConflictColumns(columns ...string) *ManagedPackageUpsertOne {
	mpc.conflict = append(mpc.conflict, sql.ConflictColumns(columns...))
	return &ManagedPackageUpsertOne{
		create: mpc,
	}
}

